def gk (k n : Nat) : Int :=
  sSup {v : Int | ∃ a : Fin k → Nat, (∀ i : Fin k, 1 ≤ a i) ∧
    ((∏ i : Fin k, (a i).factorial) ∣ n.factorial) ∧
    v = (∑ i : Fin k, ((a i : Nat) : Int)) - (n : Int)}

